function demo(){var demo_str = "order_id;\nauth_code;\ntotal_amount;";$("#content").val(demo_str);}function toCamelLine(line){return line.replace(/[-_\s]+([a-zA-Z0-9])/g,function(_,c){return c.toUpperCase();});}function toSnakeLine(line){return line.replace(/([a-z0-9])([A-Z])/g,"$1_$2").replace(/[\s-]+/g,"_").toLowerCase();}function convertCamelCase(mode){var input=$("#content").val()||"";if(!input.trim()){alert("请输入要转换的内容");return;}var lines=input.split(/\r?\n/).map(function(line){return mode===2?toCamelLine(line):toSnakeLine(line);});$("#result").text(lines.join("\n"));}
